From 3ab69123dc1f1fe03232ec918c7c718afdfb68b9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:34:27 +0100
Subject: [PATCH] ksmserver: ask the portal whether apps block logout before
 logging out

Apps that block logout through the XDG desktop portal, like GTK apps
with unsaved documents, were ignored and the session ended anyway. Ask
the KDE portal first and cancel the logout with a notification if so.

BUG: 496282
---
 ksmserver/logout.cpp | 31 ++++++++++++++++++++++++++++++-
 1 file changed, 30 insertions(+), 1 deletion(-)

diff --git a/ksmserver/logout.cpp b/ksmserver/logout.cpp
index c1daa435d7..886b655d69 100644
--- a/ksmserver/logout.cpp
+++ b/ksmserver/logout.cpp
@@ -36,6 +36,8 @@
 #include <time.h>
 #include <unistd.h>

+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
 #include <QFile>
 #include <QFutureWatcher>
 #include <QTimer>
@@ -74,7 +76,34 @@ bool KSMServer::closeSession()
         QObject::disconnect(*conn);
     });

-    performLogout();
+    if (state >= Shutdown) {
+        performLogout();
+        return false;
+    }
+
+    // Apps can block logout through the XDG desktop portal (e.g. GTK apps with unsaved documents)
+    auto query = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.impl.portal.desktop.kde"),
+                                                QStringLiteral("/org/kde/SessionState"),
+                                                QStringLiteral("org.kde.SessionState"),
+                                                QStringLiteral("queryCanEndSession"));
+    query.setAutoStartService(false);
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(query), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        const QDBusPendingReply<bool> reply = *watcher;
+        if (!reply.isError() && !reply.value() && state == Idle) {
+            qCDebug(KSMSERVER) << "Logout inhibited by an application through the portal";
+            KNotification::event(QStringLiteral("cancellogout"),
+                                 QString(),
+                                 i18n("Logout canceled because an application is preventing it"),
+                                 QString(),
+                                 KNotification::DefaultEvent,
+                                 QStringLiteral("plasma_workspace"));
+            Q_EMIT logoutFinished(false);
+            return;
+        }
+        performLogout();
+    });
     return false;
 }

